class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        min_sum = float('inf')

        # Iterate through all possible start positions
        for i in range(n):
            # Iterate through all possible end positions
            for j in range(i, n):
                # Calculate sum of subarray nums[i:j+1]
                subarray_sum = sum(nums[i:j+1])

                # Check if length is between l and r
                length = j - i + 1
                if l <= length <= r:
                    # Check if sum is positive
                    if subarray_sum > 0:
                        min_sum = min(min_sum, subarray_sum)

        return min_sum if min_sum != float('inf') else -1
```

