class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0
        for i in range(n):
            for j in range(i, n):
                # Count 0s and 1s in s[i:j+1]
                count0 = 0
                count1 = 0
                for x in s[i:j+1]:
                    if x == '0':
                        count0 += 1
                    else:
                        count1 += 1

                if count0 <= k or count1 <= k:
                    count += 1
        return count
```

