def solve():
    s = input()
    n = len(s)

    # Find all positions where S[i] = 'A'
    a_positions = []
    for i in range(n):
        if s[i] == 'A':
            a_positions.append(i)

    # Find all positions where S[j] = 'B'
    b_positions = []
    for i in range(n):
        if s[i] == 'B':
            b_positions.append(i)

    # Find all positions where S[k] = 'C'
    c_positions = []
    for i in range(n):
        if s[i] == 'C':
            c_positions.append(i)

    # Count valid triples (i, j, k)
    count = 0
    for i in a_positions:
        for j in b_positions:
            if j > i:
                for k in c_positions:
                    if k > j and j - i == k - j:
                        count += 1

    print(count)

solve()
