import sys

def main():
    # Read input from standard input
    line = sys.stdin.read().strip()
    if not line:
        return

    parts = line.split()
    L = int(parts[0])
    R = int(parts[1])

    # Check if Snuke is raising both hands or no hands
    if L == 1 and R == 1 or L == 0 and R == 0:
        print("Invalid")
    else:
        # If Snuke is raising only one hand, he is always following the instructions
        # So we just print Yes if he's raising only one hand
        if L == 1 and R == 0:
            print("Yes")
        elif L == 0 and R == 1:
            print("Yes")
        else:
            # This case shouldn't happen based on the logic above
            print("No")

if __name__ == "__main__":
    main()
```

