    if len(S) % 2 != 0:
        return False

    # Condition 2: For each i from 1 to |T|/2, T[2i-1] == T[2i]
    n = len(S)
    for i in range(1, n // 2 + 1):
        if S[2*i-1] != S[2*i]:
            return False

    # Condition 3: Each character appears exactly 0 or 2 times
    from collections import Counter
    counts = Counter(S)
    for count in counts.values():
        if count % 2 != 0:
            return False

    return True

