from typing import List

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Check if the first subarray is strictly increasing
        for i in range(n - k + 1):
            # Check if subarray starting at i is strictly increasing
            is_increasing = True
            for j in range(k - 1):
                if nums[i + j] >= nums[i + j + 1]:
                    is_increasing = False
                    break

            # If the first subarray is not strictly increasing, skip
            if not is_increasing:
                continue

            # Check if the second subarray (starting at i+k) is also strictly increasing
            is_second_increasing = True
            for j in range(k - 1):
                if nums[i + k + j] >= nums[i + k + j + 1]:
                    is_second_increasing = False
                    break

            # If both subarrays are strictly increasing, return True
            if is_second_increasing:
                return True

        return False
