class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        # Create a mapping from character to its index in s
        s_index = {char: i for i, char in enumerate(s)}

        # Create a mapping from character to its index in t
        t_index = {char: i for i, char in enumerate(t)}

        # Calculate the permutation difference
        permutation_difference = sum(
            abs(s_index[char] - t_index[char]) 
            for char in s_index
        )

        return permutation_difference
