class Solution:
    def sumOfEncryptedInt(self, nums: List[int]) -> int:
        def encrypt(x: int) -> int:
            if x == 0:
                return 0

            # Find the largest digit
            largest = 0
            temp = x
            while temp > 0:
                digit = temp % 10
                if digit > largest:
                    largest = digit
                temp //= 10

            # Replace all digits with the largest digit
            result = 0
            temp = x
            while temp > 0:
                digit = temp % 10
                result = result * 10 + largest
                temp //= 10

            return result

        return sum(encrypt(num) for num in nums)
