from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to count how many subarrays of size k each number appears in
        subarray_counts = {}

        # Get all subarrays of size k
        subarray_indices = []
        for i in range(len(nums) - k + 1):
            subarray_indices.append(i)

        # Count occurrences of each number in each subarray
        for i in range(len(nums)):
            for j in range(len(nums) - k + 1):
                subarray = nums[j:j+k]
                for num in subarray:
                    subarray_counts[num] = subarray_counts.get(num, 0) + 1

        # Find numbers that appear in exactly one subarray
        almost_missing = [num for num, count in subarray_counts.items() if count == 1]

        # Return the largest such number, or -1 if none exist
        return max(almost_missing) if almost_missing else -1
