import sys

def solve():
    # Read N and M
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Read S
    S = []
    for _ in range(N):
        S.append(next(iterator))

    # Read T
    T = []
    for _ in range(M):
        T.append(next(iterator))

    # Iterate through all possible top-left positions (a, b)
    # Using 0-based indexing for implementation, then convert to 1-based for output
    # a corresponds to row index r, b corresponds to column index c
    # 1 <= a <= N - M + 1  =>  0 <= r <= N - M
    # 1 <= b <= N - M + 1  =>  0 <= c <= N - M

    for r in range(N - M + 1):
        for c in range(N - M + 1):
            # Check if the subgrid S[r:c:r:M] matches T
            # S indices: r, r+1, ..., r+M-1
            # T indices: 0, 1, ..., M-1
            match = True
            for i in range(M):
                for j in range(M):
                    if S[r + i][c + j] != T[i][j]:
                        match = False
                        break
                if not match:
                    break
            if match:
                # Output 1-based coordinates
                print(f"{r + 1} {c + 1}")
                return

if __name__ == '__main__':
