import sys

def solve():
    # Read input from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        K = []
        for _ in range(N):
            K.append(int(next(iterator)))
    except StopIteration:
        return

    # If N=0, no departments, output 0
    if N == 0:
        print(0)
        return

    # Brute force all 2^N possible assignments
    # Since N <= 20, 2^20 = 1,048,576 which is manageable
    min_max_people = float('inf')

    # Iterate through all possible subsets for Group A
    for i in range(1 << N):
        group_a_sum = 0
        group_b_sum = 0

        for j in range(N):
            if (i >> j) & 1:
                group_a_sum += K[j]
            else:
                group_b_sum += K[j]

        max_people = max(group_a_sum, group_b_sum)
        if max_people < min_max_people:
            min_max_people = max_people

    print(min_max_people)

if __name__ == "__main__":
    solve()
