class Solution:
    def stringHash(self, s: str, k: int) -> str:
        result = []
        n = len(s)

        for i in range(0, n, k):
            substring = s[i:i+k]
            sum_hash = sum(ord(c) - ord('a') for c in substring)
            hashedChar = sum_hash % 26
            result.append(chr(hashedChar + ord('a')))

        return ''.join(result)
