class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for rows
        row_flips = 0
        for i in range(m):
            row = grid[i]
            flips = 0
            for j in range(n // 2):
                if row[j] != row[n - 1 - j]:
                    flips += 1
            row_flips += flips

        # Calculate flips needed for columns
        col_flips = 0
        for j in range(n):
            col = [grid[i][j] for i in range(m)]
            flips = 0
            for k in range(m // 2):
                if col[k] != col[m - 1 - k]:
                    flips += 1
            col_flips += flips

        return min(row_flips, col_flips)
