                    # Cannot append '0' after '0'
                    dp[length][0] += dp[length-1][1]
                # Can append '0' after '1'
                dp[length][0] += dp[length-1][1]

                # Can append '1' after '0'
                dp[length][1] += dp[length-1][0]
                # Can append '1' after '1'
