from typing import List

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        results = []

        for i in range(n - k + 1):
            # Extract the subarray
            subarray = nums[i:i+k]

            # Check if sorted in ascending order
            is_sorted = True
            for j in range(1, k):
                if subarray[j-1] > subarray[j]:
                    is_sorted = False
                    break

            # Check if consecutive (each element differs by exactly 1 from the next)
            is_consecutive = True
            for j in range(1, k):
                if subarray[j-1] - subarray[j] != 1:
                    is_consecutive = False
                    break

            # Determine power
            if is_sorted and is_consecutive:
                power = max(subarray)
            else:
                power = -1

            results.append(power)

        return results
