class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n = len(s)
        m = len(t)

        # Get all possible substrings from s
        s_substrings = []
        for i in range(n):
            for j in range(i + 1, n + 1):
                s_substrings.append(s[i:j])

        # Get all possible substrings from t
        t_substrings = []
        for i in range(m):
            for j in range(i + 1, m + 1):
                t_substrings.append(t[i:j])

        # Try all combinations
        max_len = 0
        for s_sub in s_substrings:
            for t_sub in t_substrings:
                # Check if s_sub + t_sub is a palindrome
                if (s_sub + t_sub) == (s_sub + t_sub)[::-1]:
                    max_len = max(max_len, len(s_sub + t_sub))

        return max_len
